INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000301', '50000000-0000-0000-0000-000000000025', 'simple', 'mcq', 'What is the primary purpose of a firewall?', '["Control incoming and outgoing network traffic", "Encrypt data transmissions", "Detect malware", "Manage user authentication"]', 'Control incoming and outgoing network traffic', 'A firewall monitors and controls network traffic based on predetermined security rules.', 'active'),
('60000000-0000-0000-0000-000000000302', '50000000-0000-0000-0000-000000000025', 'simple', 'mcq', 'What does VPN stand for?', '["Virtual Private Network", "Verified Private Network", "Virtual Public Network", "Verified Protected Network"]', 'Virtual Private Network', 'VPN stands for Virtual Private Network, which creates a secure connection over a public network.', 'active'),
('60000000-0000-0000-0000-000000000303', '50000000-0000-0000-0000-000000000025', 'simple', 'mcq', 'Which layer of the OSI model do traditional firewalls operate at?', '["Network Layer (Layer 3)", "Application Layer (Layer 7)", "Transport Layer (Layer 4)", "Data Link Layer (Layer 2)"]', 'Network Layer (Layer 3)', 'Traditional firewalls operate at the Network Layer, examining IP addresses and ports.', 'active'),
('60000000-0000-0000-0000-000000000304', '50000000-0000-0000-0000-000000000025', 'simple', 'mcq', 'What is the default port for IPsec VPN?', '["500", "443", "1723", "22"]', '500', 'IPsec VPN uses UDP port 500 for IKE (Internet Key Exchange) negotiations.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000305', '50000000-0000-0000-0000-000000000025', 'intermediate', 'mcq', 'What is the difference between stateful and stateless firewalls?', '["Stateful firewalls track connection state", "Stateless firewalls are faster", "Stateful firewalls only check headers", "Stateless firewalls remember sessions"]', 'Stateful firewalls track connection state', 'Stateful firewalls monitor the state of active connections, while stateless firewalls filter packets individually.', 'active'),
('60000000-0000-0000-0000-000000000306', '50000000-0000-0000-0000-000000000025', 'intermediate', 'mcq', 'Which VPN protocol is most secure?', '["IPsec with IKEv2", "PPTP", "L2TP without encryption", "SSTP"]', 'IPsec with IKEv2', 'IPsec with IKEv2 provides strong encryption and is considered more secure than PPTP or unencrypted L2TP.', 'active'),
('60000000-0000-0000-0000-000000000307', '50000000-0000-0000-0000-000000000025', 'intermediate', 'mcq', 'What is a DMZ in network security?', '["Demilitarized Zone for public-facing services", "Direct Memory Zone", "Domain Management Zone", "Data Management Zone"]', 'Demilitarized Zone for public-facing services', 'A DMZ is a network segment that sits between an internal network and the internet, hosting public services.', 'active'),
('60000000-0000-0000-0000-000000000308', '50000000-0000-0000-0000-000000000025', 'intermediate', 'code_mcq', 'Which iptables command blocks all incoming traffic?', '["iptables -P INPUT DROP", "iptables -A INPUT -j DROP", "iptables -F INPUT", "iptables -D INPUT ALL"]', 'iptables -P INPUT DROP', 'The command "iptables -P INPUT DROP" sets the default policy for the INPUT chain to DROP all packets.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000309', '50000000-0000-0000-0000-000000000025', 'expert', 'mcq', 'What is the main weakness of PPTP VPN protocol?', '["Weak encryption (MS-CHAP v2)", "Slow speed", "Complex configuration", "Limited platform support"]', 'Weak encryption (MS-CHAP v2)', 'PPTP uses MS-CHAP v2 authentication, which has known vulnerabilities and is considered insecure.', 'active'),
('60000000-0000-0000-0000-000000000310', '50000000-0000-0000-0000-000000000025', 'expert', 'mcq', 'In firewall rules, what is the difference between DROP and REJECT?', '["DROP silently discards, REJECT sends error", "REJECT is faster", "DROP sends error", "They are identical"]', 'DROP silently discards, REJECT sends error', 'DROP silently discards packets, while REJECT sends an ICMP error back to the sender.', 'active'),
('60000000-0000-0000-0000-000000000311', '50000000-0000-0000-0000-000000000025', 'expert', 'mcq', 'What is SSL/TLS inspection in next-gen firewalls?', '["Decrypting and inspecting SSL/TLS traffic", "Blocking SSL traffic", "Encrypting firewall logs", "Creating SSL certificates"]', 'Decrypting and inspecting SSL/TLS traffic', 'SSL/TLS inspection allows firewalls to decrypt secure traffic for inspection while maintaining encryption.', 'active'),
('60000000-0000-0000-0000-000000000312', '50000000-0000-0000-0000-000000000025', 'expert', 'code_mcq', 'Which command shows current iptables rules with line numbers?', '["iptables -L -n --line-numbers", "iptables --list-rules", "iptables -S", "iptables --show-all"]', 'iptables -L -n --line-numbers', 'The command "iptables -L -n --line-numbers" displays rules with line numbers and numeric addresses.', 'active'),
('60000000-0000-0000-0000-000000000313', '50000000-0000-0000-0000-000000000025', 'expert', 'mcq', 'What is the maximum number of concurrent VPN connections in Windows Server 2019?', '["Unlimited", "1000", "128", "Depends on CALs"]', 'Unlimited', 'Windows Server 2019 supports unlimited VPN connections (subject to hardware and licensing).', 'active');
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000314', '50000000-0000-0000-0000-000000000026', 'simple', 'mcq', 'What does IDS stand for?', '["Intrusion Detection System", "Intrusion Defense System", "Internet Defense System", "Intrusion Detection Software"]', 'Intrusion Detection System', 'IDS stands for Intrusion Detection System, which monitors network traffic for suspicious activity.', 'active'),
('60000000-0000-0000-0000-000000000315', '50000000-0000-0000-0000-000000000026', 'simple', 'mcq', 'What is the main difference between IDS and IPS?', '["IDS detects, IPS prevents", "IPS detects, IDS prevents", "IDS is hardware, IPS is software", "No difference"]', 'IDS detects, IPS prevents', 'IDS (Intrusion Detection System) detects threats, while IPS (Intrusion Prevention System) actively blocks them.', 'active'),
('60000000-0000-0000-0000-000000000316', '50000000-0000-0000-0000-000000000026', 'simple', 'mcq', 'Which type of IDS monitors network traffic?', '["Network-based IDS (NIDS)", "Host-based IDS (HIDS)", "Application-based IDS", "Cloud-based IDS"]', 'Network-based IDS (NIDS)', 'NIDS monitors network traffic for suspicious activity across the entire network segment.', 'active'),
('60000000-0000-0000-0000-000000000317', '50000000-0000-0000-0000-000000000026', 'simple', 'mcq', 'What does HIDS stand for?', '["Host-based Intrusion Detection System", "Hardware Intrusion Detection System", "Hybrid Intrusion Detection System", "High-performance Intrusion Detection System"]', 'Host-based Intrusion Detection System', 'HIDS monitors activities on individual hosts or devices for signs of intrusion.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000318', '50000000-0000-0000-0000-000000000026', 'intermediate', 'mcq', 'What is signature-based detection in IDS?', '["Matches patterns against known attack signatures", "Analyzes behavior anomalies", "Uses machine learning", "Blocks all unknown traffic"]', 'Matches patterns against known attack signatures', 'Signature-based detection compares network traffic against a database of known attack patterns.', 'active'),
('60000000-0000-0000-0000-000000000319', '50000000-0000-0000-0000-000000000026', 'intermediate', 'mcq', 'What is a false positive in IDS/IPS?', '["Legitimate traffic flagged as malicious", "Malicious traffic not detected", "System crash", "Configuration error"]', 'Legitimate traffic flagged as malicious', 'A false positive occurs when normal, legitimate activity is incorrectly identified as malicious.', 'active'),
('60000000-0000-0000-0000-000000000320', '50000000-0000-0000-0000-000000000026', 'intermediate', 'mcq', 'Which open-source IDS is widely used?', '["Snort", "Wireshark", "Nmap", "Metasploit"]', 'Snort', 'Snort is a popular open-source network intrusion detection and prevention system.', 'active'),
('60000000-0000-0000-0000-000000000321', '50000000-0000-0000-0000-000000000026', 'intermediate', 'code_mcq', 'Which Snort rule option matches content in packet payload?', '["content", "msg", "sid", "rev"]', 'content', 'The "content" option in Snort rules is used to search for specific patterns in packet payloads.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000322', '50000000-0000-0000-0000-000000000026', 'expert', 'mcq', 'What is the main limitation of signature-based detection?', '["Cannot detect zero-day attacks", "High false positive rate", "Slow performance", "Complex configuration"]', 'Cannot detect zero-day attacks', 'Signature-based detection cannot detect new, unknown attacks (zero-days) that are not in its signature database.', 'active'),
('60000000-0000-0000-0000-000000000323', '50000000-0000-0000-0000-000000000026', 'expert', 'mcq', 'What is inline mode in IPS deployment?', '["IPS sits directly in traffic path", "IPS monitors mirrored traffic", "IPS analyzes logs only", "IPS works offline"]', 'IPS sits directly in traffic path', 'In inline mode, the IPS is placed directly in the network traffic path and can actively block malicious packets.', 'active'),
('60000000-0000-0000-0000-000000000324', '50000000-0000-0000-0000-000000000026', 'expert', 'mcq', 'What is the difference between promiscuous and non-promiscuous mode in NIDS?', '["Promiscuous mode sees all packets", "Non-promiscuous is faster", "Promiscuous filters packets", "No difference"]', 'Promiscuous mode sees all packets', 'In promiscuous mode, the network interface card passes all traffic to the NIDS, not just traffic addressed to it.', 'active'),
('60000000-0000-0000-0000-000000000325', '50000000-0000-0000-0000-000000000026', 'expert', 'code_mcq', 'Which Suricata rule option detects buffer overflow attempts?', '["byte_test", "content", "msg", "classtype"]', 'byte_test', 'The "byte_test" option in Suricata can be used to detect buffer overflow attempts by checking field values.', 'active'),
('60000000-0000-0000-0000-000000000326', '50000000-0000-0000-0000-000000000026', 'expert', 'mcq', 'What is the maximum throughput of Snort 3.0?', '["100 Gbps", "1 Gbps", "10 Gbps", "1 Tbps"]', '100 Gbps', 'Snort 3.0 is designed to handle up to 100 Gbps throughput on appropriate hardware.', 'active');
INSERT INTO subjects (id, domain_id, name, status) 
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000327', '50000000-0000-0000-0000-000000000027', 'simple', 'mcq', 'What is the difference between symmetric and asymmetric encryption?', '["Symmetric uses one key, asymmetric uses two", "Asymmetric is faster", "Symmetric is more secure", "No difference"]', 'Symmetric uses one key, asymmetric uses two', 'Symmetric encryption uses the same key for encryption and decryption, while asymmetric uses a public/private key pair.', 'active'),
('60000000-0000-0000-0000-000000000328', '50000000-0000-0000-0000-000000000027', 'simple', 'mcq', 'Which algorithm is an example of symmetric encryption?', '["AES", "RSA", "ECC", "DSA"]', 'AES', 'AES (Advanced Encryption Standard) is a symmetric encryption algorithm.', 'active'),
('60000000-0000-0000-0000-000000000329', '50000000-0000-0000-0000-000000000027', 'simple', 'mcq', 'What does AES stand for?', '["Advanced Encryption Standard", "Advanced Encryption System", "Asymmetric Encryption Standard", "American Encryption Standard"]', 'Advanced Encryption Standard', 'AES stands for Advanced Encryption Standard, a symmetric encryption algorithm.', 'active'),
('60000000-0000-0000-0000-000000000330', '50000000-0000-0000-0000-000000000027', 'simple', 'mcq', 'Which algorithm is commonly used for asymmetric encryption?', '["RSA", "AES", "DES", "3DES"]', 'RSA', 'RSA is a widely used asymmetric encryption algorithm.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000331', '50000000-0000-0000-0000-000000000027', 'intermediate', 'mcq', 'What is the minimum recommended key length for RSA?', '["2048 bits", "1024 bits", "512 bits", "4096 bits"]', '2048 bits', '2048-bit RSA keys are currently considered secure, while 1024-bit keys are being phased out.', 'active'),
('60000000-0000-0000-0000-000000000332', '50000000-0000-0000-0000-000000000027', 'intermediate', 'mcq', 'Which encryption mode is vulnerable to padding oracle attacks?', '["CBC", "GCM", "CTR", "ECB"]', 'CBC', 'CBC (Cipher Block Chaining) mode can be vulnerable to padding oracle attacks if not implemented correctly.', 'active'),
('60000000-0000-0000-0000-000000000333', '50000000-0000-0000-0000-000000000027', 'intermediate', 'mcq', 'What is the main advantage of ECC over RSA?', '["Smaller key sizes for same security", "Faster encryption", "Simpler implementation", "Better compatibility"]', 'Smaller key sizes for same security', 'ECC provides equivalent security with much smaller key sizes compared to RSA.', 'active'),
('60000000-0000-0000-0000-000000000334', '50000000-0000-0000-0000-000000000027', 'intermediate', 'code_mcq', 'Which OpenSSL command generates an RSA private key?', '["openssl genrsa -out key.pem 2048", "openssl rsa -generate 2048", "openssl create rsa-key 2048", "openssl newkey rsa:2048"]', 'openssl genrsa -out key.pem 2048', 'The command "openssl genrsa -out key.pem 2048" generates a 2048-bit RSA private key.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000001135', '50000000-0000-0000-0000-000000000027', 'expert', 'mcq', 'What is the quantum computing threat to RSA?', '["Shor''s algorithm can break RSA", "Grover''s algorithm breaks AES", "Quantum annealing breaks ECC", "No threat exists"]', 'Shor''s algorithm can break RSA', 'Shor''s algorithm, when run on a sufficiently large quantum computer, could break RSA encryption.', 'active'),
('60000000-0000-0000-0000-000000001136', '50000000-0000-0000-0000-000000000027', 'expert', 'mcq', 'What is post-quantum cryptography?', '["Cryptography resistant to quantum attacks", "Cryptography using quantum principles", "Faster classical cryptography", "Obsolete cryptography"]', 'Cryptography resistant to quantum attacks', 'Post-quantum cryptography refers to cryptographic algorithms that are secure against quantum computer attacks.', 'active'),
('60000000-0000-0000-0000-000000001137', '50000000-0000-0000-0000-000000000027', 'expert', 'mcq', 'Which AES key length is considered most secure?', '["256-bit", "128-bit", "192-bit", "512-bit"]', '256-bit', 'AES-256 is currently considered the most secure, though AES-128 is still secure for most applications.', 'active'),
('60000000-0000-0000-0000-000000001138', '50000000-0000-0000-0000-000000000027', 'expert', 'code_mcq', 'Which Python library function performs AES encryption?', '["Crypto.Cipher.AES.new()", "cryptography.aes.encrypt()", "pycrypto.aes_cipher()", "ssl.aes_encrypt()"]', 'Crypto.Cipher.AES.new()', 'In Python''s pycryptodome library, Crypto.Cipher.AES.new() creates an AES cipher object.', 'active'),
('60000000-0000-0000-0000-000000001139', '50000000-0000-0000-0000-000000000027', 'expert', 'mcq', 'What is the maximum key size for AES?', '["256 bits", "128 bits", "512 bits", "1024 bits"]', '256 bits', 'AES supports key sizes of 128, 192, or 256 bits, with 256 being the maximum.', 'active');
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000340', '50000000-0000-0000-0000-000000000028', 'simple', 'mcq', 'What does PKI stand for?', '["Public Key Infrastructure", "Private Key Index", "Public Key Interface", "Protocal Key Infrastructure"]', 'Public Key Infrastructure', 'PKI is the framework that manages digital certificates and public-key encryption.', 'active'),
('60000000-0000-0000-0000-000000000341', '50000000-0000-0000-0000-000000000028', 'simple', 'mcq', 'What is a Certificate Authority (CA)?', '["Trusted entity that issues digital certificates", "Entity that encrypts data", "Security software", "Network protocol"]', 'Trusted entity that issues digital certificates', 'A CA is a trusted third party that validates identities and issues digital certificates.', 'active'),
('60000000-0000-0000-0000-000000000342', '50000000-0000-0000-0000-000000000028', 'simple', 'mcq', 'What is a CSR?', '["Certificate Signing Request", "Certificate Security Record", "Client Security request", "Code Signing Record"]', 'Certificate Signing Request', 'A CSR is a message sent to a CA to apply for a digital identity certificate.', 'active'),
('60000000-0000-0000-0000-000000000343', '50000000-0000-0000-0000-000000000028', 'simple', 'mcq', 'What is the purpose of a CRL?', '["List of revoked certificates", "Certificate Root List", "Client Revocation Link", "Central Recovery Log"]', 'List of revoked certificates', 'A Certificate Revocation List (CRL) contains certificates that have been revoked before their expiration date.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000344', '50000000-0000-0000-0000-000000000028', 'intermediate', 'mcq', 'What is OCSP targeting?', '["Real-time status of a certificate", "Encrypting mail", "Code signing", "User authentication"]', 'Real-time status of a certificate', 'Online Certificate Status Protocol (OCSP) is used to obtain the revocation status of an X.509 digital certificate.', 'active'),
('60000000-0000-0000-0000-000000000345', '50000000-0000-0000-0000-000000000028', 'intermediate', 'mcq', 'What is a root certificate?', '["Top-level certificate in a chain of trust", "A self-signed private key", "An expired certificate", "A temporary key"]', 'Top-level certificate in a chain of trust', 'A root certificate is the ultimate trust anchor in a PKI environment.', 'active'),
('60000000-0000-0000-0000-000000000346', '50000000-0000-0000-0000-000000000028', 'intermediate', 'mcq', 'What is pinning in certificate management?', '["Associating a host with its expected certificate", "Deleting old certs", "Creating new keys", "Renewing certificates"]', 'Associating a host with its expected certificate', 'Certificate pinning reduces the risk of man-in-the-middle attacks by defining which certificates are valid for a particular host.', 'active'),
('60000000-0000-0000-0000-000000000347', '50000000-0000-0000-0000-000000000028', 'intermediate', 'code_mcq', 'Which OpenSSL command creates a CSR using an existing private key?', '["openssl req -new -key key.pem -out csr.pem", "openssl csr -new -key key.pem", "openssl req -gen-csr -key key.pem", "openssl create csr.pem"]', 'openssl req -new -key key.pem -out csr.pem', 'This command generates a new CSR using the provided private key.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000348', '50000000-0000-0000-0000-000000000028', 'expert', 'mcq', 'What is certificate pinning?', '["Associating host with expected certificate", "Revoking certificates", "Encrypting certificates", "Backing up certificates"]', 'Associating host with expected certificate', 'Certificate pinning associates a host with its expected certificate to prevent MITM attacks.', 'active'),
('60000000-0000-0000-0000-000000000349', '50000000-0000-0000-0000-000000000028', 'expert', 'mcq', 'What is the difference between DV, OV, and EV certificates?', '["Different validation levels", "Different encryption strengths", "Different algorithms", "Different file formats"]', 'Different validation levels', 'DV (Domain Validation) verifies domain control, OV (Organization Validation) verifies organization, EV (Extended Validation) provides highest assurance.', 'active'),
('60000000-0000-0000-0000-000000000350', '50000000-0000-0000-0000-000000000028', 'expert', 'mcq', 'What is a wildcard certificate?', '["Certificate covering subdomains", "Expired certificate", "Self-signed certificate", "Test certificate"]', 'Certificate covering subdomains', 'A wildcard certificate secures a domain and all its subdomains (e.g., *.example.com).', 'active'),
('60000000-0000-0000-0000-000000000351', '50000000-0000-0000-0000-000000000028', 'expert', 'code_mcq', 'Which command checks certificate expiration date?', '["openssl x509 -in cert.pem -noout -enddate", "openssl check-expiry cert.pem", "openssl cert -expires cert.pem", "openssl verify -expiry cert.pem"]', 'openssl x509 -in cert.pem -noout -enddate', 'The command "openssl x509 -in cert.pem -noout -enddate" displays the certificate expiration date.', 'active'),
('60000000-0000-0000-0000-000000000352', '50000000-0000-0000-0000-000000000028', 'expert', 'mcq', 'What is the maximum validity period for TLS certificates?', '["398 days", "3 years", "5 years", "10 years"]', '398 days', 'As per CA/Browser Forum guidelines, TLS certificates cannot be valid for more than 398 days.', 'active');
INSERT INTO subjects (id, domain_id, name, status) 
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000353', '50000000-0000-0000-0000-000000000029', 'simple', 'mcq', 'What does OWASP stand for?', '["Open Web Application Security Project", "Open Website Security Protocol", "Online Web Application Security Platform", "Open Web Authentication Security Project"]', 'Open Web Application Security Project', 'OWASP stands for Open Web Application Security Project, a nonprofit foundation that works to improve software security.', 'active'),
('60000000-0000-0000-0000-000000000354', '50000000-0000-0000-0000-000000000029', 'simple', 'mcq', 'Which vulnerability is #1 in OWASP Top 10 2021?', '["Broken Access Control", "Injection", "Cryptographic Failures", "Identification and Authentication Failures"]', 'Broken Access Control', 'In OWASP Top 10 2021, Broken Access Control moved to the #1 position from #5 in 2017.', 'active'),
('60000000-0000-0000-0000-000000000355', '50000000-0000-0000-0000-000000000029', 'simple', 'mcq', 'What is SQL Injection?', '["Injecting malicious SQL code", "Database encryption", "SQL optimization", "Database backup"]', 'Injecting malicious SQL code', 'SQL Injection occurs when an attacker inserts malicious SQL code into database queries.', 'active'),
('60000000-0000-0000-0000-000000000356', '50000000-0000-0000-0000-000000000029', 'simple', 'mcq', 'What is XSS?', '["Cross-Site Scripting", "Cross-Site Security", "XML Site Scripting", "Cross-Site Scanning"]', 'Cross-Site Scripting', 'XSS stands for Cross-Site Scripting, where attackers inject client-side scripts into web pages.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000357', '50000000-0000-0000-0000-000000000029', 'intermediate', 'mcq', 'What is the difference between stored and reflected XSS?', '["Stored persists, reflected doesn''t", "Reflected is more dangerous", "Stored is in memory only", "No difference"]', 'Stored persists, reflected doesn''t', 'Stored XSS is permanently stored on the server, while reflected XSS is included in the response to a specific request.', 'active'),
('60000000-0000-0000-0000-000000000358', '50000000-0000-0000-0000-000000000029', 'intermediate', 'mcq', 'What is CSRF?', '["Cross-Site Request Forgery", "Cross-Site Response Forgery", "Client-Side Request Forgery", "Cross-Site Resource Forgery"]', 'Cross-Site Request Forgery', 'CSRF stands for Cross-Site Request Forgery, where attackers trick users into performing unwanted actions.', 'active'),
('60000000-0000-0000-0000-000000000359', '50000000-0000-0000-0000-000000000029', 'intermediate', 'mcq', 'Which OWASP category includes vulnerabilities like buffer overflows?', '["Insecure Design", "Software and Data Integrity Failures", "Security Misconfiguration", "Vulnerable and Outdated Components"]', 'Insecure Design', 'Insecure Design includes flaws in architecture and design, such as buffer overflows and race conditions.', 'active'),
('60000000-0000-0000-0000-000000000360', '50000000-0000-0000-0000-000000000029', 'intermediate', 'code_mcq', 'Which SQL keyword can prevent SQL injection in PHP?', '["prepare() and execute()", "mysql_real_escape_string()", "addslashes()", "htmlspecialchars()"]', 'prepare() and execute()', 'Using prepared statements with prepare() and execute() is the most effective way to prevent SQL injection in PHP.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000361', '50000000-0000-0000-0000-000000000029', 'expert', 'mcq', 'What is the main weakness of PPTP VPN protocol?', '["Weak encryption (MS-CHAP v2)", "Slow speed", "Complex configuration", "Limited platform support"]', 'Weak encryption (MS-CHAP v2)', 'PPTP uses MS-CHAP v2 authentication, which has known vulnerabilities and is considered insecure.', 'active'),
('60000000-0000-0000-0000-000000000362', '50000000-0000-0000-0000-000000000029', 'expert', 'mcq', 'In firewall rules, what is the difference between DROP and REJECT?', '["DROP silently discards, REJECT sends error", "REJECT is faster", "DROP sends error", "They are identical"]', 'DROP silently discards, REJECT sends error', 'DROP silently discards packets, while REJECT sends an ICMP error back to the sender.', 'active'),
('60000000-0000-0000-0000-000000000363', '50000000-0000-0000-0000-000000000029', 'expert', 'mcq', 'What is SSL/TLS inspection in next-gen firewalls?', '["Decrypting and inspecting SSL/TLS traffic", "Blocking SSL traffic", "Encrypting firewall logs", "Creating SSL certificates"]', 'Decrypting and inspecting SSL/TLS traffic', 'SSL/TLS inspection allows firewalls to decrypt secure traffic for inspection while maintaining encryption.', 'active'),
('60000000-0000-0000-0000-000000000364', '50000000-0000-0000-0000-000000000029', 'expert', 'code_mcq', 'Which command shows current iptables rules with line numbers?', '["iptables -L -n --line-numbers", "iptables --list-rules", "iptables -S", "iptables --show-all"]', 'iptables -L -n --line-numbers', 'The command "iptables -L -n --line-numbers" displays rules with line numbers and numeric addresses.', 'active'),
('60000000-0000-0000-0000-000000000365', '50000000-0000-0000-0000-000000000029', 'expert', 'mcq', 'What is the maximum number of concurrent VPN connections in Windows Server 2019?', '["Unlimited", "1000", "128", "Depends on CALs"]', 'Unlimited', 'Windows Server 2019 supports unlimited VPN connections (subject to hardware and licensing).', 'active');
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000366', '50000000-0000-0000-0000-000000000030', 'simple', 'mcq', 'What is input validation?', '["Checking and sanitizing user input", "Encrypting input", "Storing input securely", "Logging input"]', 'Checking and sanitizing user input', 'Input validation ensures that only properly formatted data enters a system, preventing many attacks.', 'active'),
('60000000-0000-0000-0000-000000000367', '50000000-0000-0000-0000-000000000030', 'simple', 'mcq', 'What is the principle of least privilege?', '["Users get minimum access needed", "All users get admin rights", "No access control", "Random access assignment"]', 'Users get minimum access needed', 'The principle of least privilege means users and processes should have only the minimum access necessary.', 'active'),
('60000000-0000-0000-0000-000000000368', '50000000-0000-0000-0000-000000000030', 'simple', 'mcq', 'What is defense in depth?', '["Multiple layers of security", "Single strong security layer", "No security layers", "Outsourcing security"]', 'Multiple layers of security', 'Defense in depth uses multiple security controls in series so if one fails, others provide protection.', 'active'),
('60000000-0000-0000-0000-000000000369', '50000000-0000-0000-0000-000000000030', 'simple', 'mcq', 'What is output encoding?', '["Encoding data before output to prevent injection", "Encrypting output", "Compressing output", "Logging output"]', 'Encoding data before output to prevent injection', 'Output encoding transforms special characters to prevent XSS and other injection attacks.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000370', '50000000-0000-0000-0000-000000000030', 'intermediate', 'mcq', 'What is parameterized queries?', '["SQL queries with placeholders for parameters", "Encrypted SQL queries", "Compressed SQL queries", "Logged SQL queries"]', 'SQL queries with placeholders for parameters', 'Parameterized queries separate SQL code from data, preventing SQL injection attacks.', 'active'),
('60000000-0000-0000-0000-000000000371', '50000000-0000-0000-0000-000000000030', 'intermediate', 'mcq', 'What is secure cookie flag?', '["Cookie attribute for secure transmission", "Cookie encryption", "Cookie compression", "Cookie logging"]', 'Cookie attribute for secure transmission', 'The Secure flag ensures cookies are only sent over HTTPS connections.', 'active'),
('60000000-0000-0000-0000-000000000372', '50000000-0000-0000-0000-000000000030', 'intermediate', 'mcq', 'What is the purpose of HTTPOnly cookie flag?', '["Prevent client-side script access to cookie", "Encrypt cookie", "Compress cookie", "Log cookie access"]', 'Prevent client-side script access to cookie', 'The HTTPOnly flag prevents client-side scripts from accessing cookies, mitigating XSS attacks.', 'active'),
('60000000-0000-0000-0000-000000000373', '50000000-0000-0000-0000-000000000030', 'intermediate', 'code_mcq', 'Which Python function escapes HTML special characters?', '["html.escape()", "urllib.parse.quote()", "base64.encode()", "json.dumps()"]', 'html.escape()', 'html.escape() converts characters like <, >, and & to HTML entities, preventing XSS.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000374', '50000000-0000-0000-0000-000000000030', 'expert', 'mcq', 'What is memory-safe programming?', '["Preventing memory corruption vulnerabilities", "Encrypting memory", "Compressing memory", "Logging memory usage"]', 'Preventing memory corruption vulnerabilities', 'Memory-safe languages and practices prevent buffer overflows, use-after-free, and other memory corruption issues.', 'active'),
('60000000-0000-0000-0000-000000000375', '50000000-0000-0000-0000-000000000030', 'expert', 'mcq', 'What is the difference between blacklist and whitelist validation?', '["Whitelist allows only known good, blacklist blocks known bad", "Blacklist is more secure", "Whitelist blocks everything", "No difference"]', 'Whitelist allows only known good, blacklist blocks known bad', 'Whitelist validation allows only pre-approved values, while blacklist blocks known malicious values.', 'active'),
('60000000-0000-0000-0000-000000000376', '50000000-0000-0000-0000-000000000030', 'expert', 'mcq', 'What is secure session management?', '["Proper generation, storage, and destruction of session tokens", "Encrypting all sessions", "Compressing session data", "Logging all sessions"]', 'Proper generation, storage, and destruction of session tokens', 'Secure session management includes using strong tokens, secure storage, proper expiration, and secure destruction.', 'active'),
('60000000-0000-0000-0000-000000000377', '50000000-0000-0000-0000-000000000030', 'expert', 'code_mcq', 'Which Java method prevents SQL injection?', '["PreparedStatement.executeQuery()", "Statement.executeQuery()", "Connection.createStatement()", "ResultSet.getString()"]', 'PreparedStatement.executeQuery()', 'Using PreparedStatement with parameterized queries prevents SQL injection in Java.', 'active'),
('60000000-0000-0000-0000-000000000378', '50000000-0000-0000-0000-000000000030', 'expert', 'mcq', 'What is the minimum recommended length for session IDs?', '["128 bits (16 bytes)", "64 bits", "256 bits", "512 bits"]', '128 bits (16 bytes)', 'Session IDs should be at least 128 bits (16 bytes) to resist brute-force guessing attacks.', 'active');
INSERT INTO subjects (id, domain_id, name, status) 
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000379', '50000000-0000-0000-0000-000000000031', 'simple', 'mcq', 'What are the main phases of incident response?', '["Preparation, Identification, Containment, Eradication, Recovery, Lessons Learned", "Detection, Analysis, Response", "Prevention, Detection, Response", "Planning, Execution, Review"]', 'Preparation, Identification, Containment, Eradication, Recovery, Lessons Learned', 'The NIST incident response framework includes these six phases.', 'active'),
('60000000-0000-0000-0000-000000000380', '50000000-0000-0000-0000-000000000031', 'simple', 'mcq', 'What is the first step in incident response?', '["Preparation", "Identification", "Containment", "Eradication"]', 'Preparation', 'Preparation is the first phase, involving planning, training, and tool preparation before incidents occur.', 'active'),
('60000000-0000-0000-0000-000000000381', '50000000-0000-0000-0000-000000000031', 'simple', 'mcq', 'What is an incident response plan?', '["Documented process for handling security incidents", "Insurance policy", "Backup plan", "Disaster recovery plan"]', 'Documented process for handling security incidents', 'An incident response plan outlines procedures for detecting, responding to, and recovering from security incidents.', 'active'),
('60000000-0000-0000-0000-000000000382', '50000000-0000-0000-0000-000000000031', 'simple', 'mcq', 'What is the purpose of containment?', '["Prevent incident from spreading", "Identify the attacker", "Recover systems", "Learn from incident"]', 'Prevent incident from spreading', 'Containment aims to limit the damage and prevent the incident from affecting more systems.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000383', '50000000-0000-0000-0000-000000000031', 'intermediate', 'mcq', 'What is the difference between eradication and recovery?', '["Eradication removes cause, recovery restores systems", "They are the same", "Recovery removes cause", "Eradication restores systems"]', 'Eradication removes cause, recovery restores systems', 'Eradication removes the root cause of the incident, while recovery restores systems to normal operation.', 'active'),
('60000000-0000-0000-0000-000000000384', '50000000-0000-0000-0000-000000000031', 'intermediate', 'mcq', 'What is a CSIRT?', '["Computer Security Incident Response Team", "Computer System Incident Recovery Team", "Cyber Security Incident Response Team", "Critical Security Incident Response Team"]', 'Computer Security Incident Response Team', 'CSIRT stands for Computer Security Incident Response Team, responsible for handling security incidents.', 'active'),
('60000000-0000-0000-0000-000000000385', '50000000-0000-0000-0000-000000000031', 'intermediate', 'mcq', 'What is the purpose of lessons learned phase?', '["Improve future incident response", "Punish responsible parties", "Document for legal purposes", "Celebrate success"]', 'Improve future incident response', 'The lessons learned phase analyzes what happened and improves processes for future incidents.', 'active'),
('60000000-0000-0000-0000-000000000386', '50000000-0000-0000-0000-000000000031', 'intermediate', 'code_mcq', 'Which tool is commonly used for log analysis in incident response?', '["Splunk", "Wireshark", "Nmap", "Metasploit"]', 'Splunk', 'Splunk is widely used for collecting, analyzing, and visualizing log data during incident response.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000387', '50000000-0000-0000-0000-000000000031', 'expert', 'mcq', 'What is the difference between incident severity and priority?', '["Severity measures impact, priority determines order", "They are the same", "Severity determines order", "Priority measures impact"]', 'Severity measures impact, priority determines order', 'Severity measures the technical impact of an incident, while priority determines the order of response based on business impact.', 'active'),
('60000000-0000-0000-0000-000000000388', '50000000-0000-0000-0000-000000000031', 'expert', 'mcq', 'What is kill chain analysis in incident response?', '["Mapping attacker''s steps from initial access to objective", "Terminating processes", "Chain of command", "Legal chain of custody"]', 'Mapping attacker''s steps from initial access to objective', 'Kill chain analysis maps the stages of an attack to understand and disrupt the attacker''s methodology.', 'active'),
('60000000-0000-0000-0000-000000000389', '50000000-0000-0000-0000-000000000031', 'expert', 'mcq', 'What is the maximum time for initial response in a critical incident?', '["15 minutes", "1 hour", "4 hours", "24 hours"]', '15 minutes', 'For critical incidents, initial response should begin within 15 minutes of detection.', 'active'),
('60000000-0000-0000-0000-000000000390', '50000000-0000-0000-0000-000000000031', 'expert', 'code_mcq', 'Which command captures network traffic for analysis?', '["tcpdump -i eth0 -w capture.pcap", "netstat -an", "nmap -sS target", "wireshark -k"]', 'tcpdump -i eth0 -w capture.pcap', 'tcpdump -i eth0 -w capture.pcap captures traffic on interface eth0 and saves to capture.pcap file.', 'active'),
('60000000-0000-0000-0000-000000000391', '50000000-0000-0000-0000-000000000031', 'expert', 'mcq', 'What is the minimum retention period for incident response logs?', '["90 days", "30 days", "1 year", "7 days"]', '90 days', 'NIST recommends retaining incident-related logs for at least 90 days for analysis and legal purposes.', 'active');
INSERT INTO topics (id, subject_id, name, status) 
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000392', '50000000-0000-0000-0000-000000000032', 'simple', 'mcq', 'What is digital forensics?', '["Process of collecting and analyzing digital evidence", "Data encryption", "Network monitoring", "Incident detection"]', 'Process of collecting and analyzing digital evidence', 'Digital forensics involves preserving, collecting, validating, analyzing, and presenting digital evidence.', 'active'),
('60000000-0000-0000-0000-000000000393', '50000000-0000-0000-0000-000000000032', 'simple', 'mcq', 'What is the first rule of digital forensics?', '["Do not alter the original evidence", "Make backups", "Analyze quickly", "Use proprietary tools"]', 'Do not alter the original evidence', 'The fundamental rule is to preserve the original evidence in its original state.', 'active'),
('60000000-0000-0000-0000-000000000394', '50000000-0000-0000-0000-000000000032', 'simple', 'mcq', 'What is a write blocker?', '["Device that prevents writing to storage media", "Firewall rule", "Memory protection", "File permission"]', 'Device that prevents writing to storage media', 'A write blocker is a hardware or software tool that prevents modification of evidence during acquisition.', 'active'),
('60000000-0000-0000-0000-000000000395', '50000000-0000-0000-0000-000000000032', 'simple', 'mcq', 'What is chain of custody?', '["Documented trail of evidence handling", "Encryption chain", "Network path", "Legal document"]', 'Documented trail of evidence handling', 'Chain of custody documents who handled evidence, when, why, and what changes were made.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000396', '50000000-0000-0000-0000-000000000032', 'intermediate', 'mcq', 'What is the difference between logical and physical acquisition?', '["Logical gets files, physical gets bit-by-bit copy", "Physical is faster", "Logical is more complete", "No difference"]', 'Logical gets files, physical gets bit-by-bit copy', 'Logical acquisition copies files and folders, while physical acquisition copies every bit on the storage device.', 'active'),
('60000000-0000-0000-0000-000000000397', '50000000-0000-0000-0000-000000000032', 'intermediate', 'mcq', 'What is memory forensics?', '["Analysis of RAM contents", "Hard disk analysis", "Network traffic analysis", "Log analysis"]', 'Analysis of RAM contents', 'Memory forensics analyzes the contents of a computer''s volatile memory (RAM) for evidence.', 'active'),
('60000000-0000-0000-0000-000000000398', '50000000-0000-0000-0000-000000000032', 'intermediate', 'mcq', 'Which tool is commonly used for disk imaging?', '["FTK Imager", "Wireshark", "Nmap", "Metasploit"]', 'FTK Imager', 'FTK Imager is a popular tool for creating forensic images of storage devices.', 'active'),
('60000000-0000-0000-0000-000000000399', '50000000-0000-0000-0000-000000000032', 'intermediate', 'code_mcq', 'Which command creates MD5 hash of a file?', '["md5sum filename", "hash filename md5", "checksum -a md5 filename", "md5 filename"]', 'md5sum filename', 'The command "md5sum filename" calculates the MD5 hash of a file for integrity verification.', 'active');
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
('60000000-0000-0000-0000-000000000400', '50000000-0000-0000-0000-000000000032', 'expert', 'mcq', 'What is slack space?', '["Unused space between end of file and end of cluster", "Empty disk space", "Compressed space", "Encrypted space"]', 'Unused space between end of file and end of cluster', 'Slack space is the unused space in a disk cluster that can contain remnants of previously deleted files.', 'active'),
('60000000-0000-0000-0000-000000000401', '50000000-0000-0000-0000-000000000032', 'expert', 'mcq', 'What is the difference between MD5 and SHA-256 for forensics?', '["SHA-256 is more secure", "MD5 is faster", "SHA-256 produces shorter hash", "No difference"]', 'SHA-256 is more secure', 'SHA-256 produces a 256-bit hash and is more secure against collisions than MD5 (128-bit).', 'active'),
('60000000-0000-0000-0000-000000000402', '50000000-0000-0000-0000-000000000032', 'expert', 'mcq', 'What is live forensics?', '["Collecting evidence from running system", "Analyzing dead system", "Real-time monitoring", "Network forensics"]', 'Collecting evidence from running system', 'Live forensics involves collecting evidence from systems that are still running to capture volatile data.', 'active'),
('60000000-0000-0000-0000-000000000403', '50000000-0000-0000-0000-000000000032', 'expert', 'code_mcq', 'Which Volatility plugin extracts process list from memory dump?', '["pslist", "pstree", "psxview", "psscan"]', 'pslist', 'The "pslist" plugin in Volatility extracts the list of running processes from a memory dump.', 'active'),
('60000000-0000-0000-0000-000000000404', '50000000-0000-0000-0000-000000000032', 'expert', 'mcq', 'What is the minimum size for a forensic copy of a 1TB drive?', '["1TB", "500GB", "2TB", "Depends on used space"]', '1TB', 'A forensic image must be a complete bit-by-bit copy, so it will be at least the same size as the original drive.', 'active');
